program expense_reimbursement
uses expenses.pending, expenses.get, directory.lookup, payroll.reimburse, mail.send, llm
budget usd 0.50

type Classification = "business" | "personal" | "unclear"
type Result = { expense_id: Str, status: Str }

fn main() -> List[Result] max 20 {
  let pending_ids = expenses.pending()
  return for id in pending_ids {
    process_expense(id)
  }
}

fn process_expense(expense_id: Str) -> Result {
  let expense = expenses.get(expense_id)
  let employee = directory.lookup(expense.employee_email)

  # Ask LLM to classify the expense
  let classification = llm.ask(Classification, "Classify this expense note as business, personal, or unclear: {expense.note}") retry 1

  # Determine the status and take action
  if expense.currency != "EUR" or classification == "unclear" {
    mail.send(to: employee.manager_email, subject: "Expense {expense_id} needs review", body: "")
    return { expense_id: expense_id, status: "needs review" }
  }

  if classification == "personal" {
    mail.send(to: employee.email, subject: "Expense {expense_id} rejected", body: "")
    return { expense_id: expense_id, status: "rejected" }
  }

  if expense.amount > employee.reimbursement_limit {
    mail.send(to: employee.manager_email, subject: "Expense {expense_id} needs review", body: "")
    return { expense_id: expense_id, status: "needs review" }
  }

  payroll.reimburse(employee_id: employee.id, amount: expense.amount, expense_id: expense_id)
  return { expense_id: expense_id, status: "reimbursed" }
}

